**Answer. **For a legal tic-tac-toe position, encode empty=0, X=1, O=2 and assume X moves first. Require X count to equal O count or exceed it by one, forbid both players winning, and relate any winner to the move counts. These conditions describe reachable standard 3x3 positions when play stops at a win.

```systemverilog
class tic_tac_toe;
  rand int board[9];
  rand bit xwin, owin;
  constraint c {
    foreach (board[i]) board[i] inside {[0:2]};
    (board.sum() with (int'(item == 1)) ==
     board.sum() with (int'(item == 2))) ||
    (board.sum() with (int'(item == 1)) ==
     (board.sum() with (int'(item == 2))) + 1);
    xwin == (
      (board[0]==1 && board[1]==1 && board[2]==1) ||
      (board[3]==1 && board[4]==1 && board[5]==1) ||
      (board[6]==1 && board[7]==1 && board[8]==1) ||
      (board[0]==1 && board[3]==1 && board[6]==1) ||
      (board[1]==1 && board[4]==1 && board[7]==1) ||
      (board[2]==1 && board[5]==1 && board[8]==1) ||
      (board[0]==1 && board[4]==1 && board[8]==1) ||
      (board[2]==1 && board[4]==1 && board[6]==1));
    owin == (
      (board[0]==2 && board[1]==2 && board[2]==2) ||
      (board[3]==2 && board[4]==2 && board[5]==2) ||
      (board[6]==2 && board[7]==2 && board[8]==2) ||
      (board[0]==2 && board[3]==2 && board[6]==2) ||
      (board[1]==2 && board[4]==2 && board[7]==2) ||
      (board[2]==2 && board[5]==2 && board[8]==2) ||
      (board[0]==2 && board[4]==2 && board[8]==2) ||
      (board[2]==2 && board[4]==2 && board[6]==2));
    !(xwin && owin);
    if (xwin) board.sum() with (int'(item == 1)) ==
              (board.sum() with (int'(item == 2))) + 1;
    if (owin) board.sum() with (int'(item == 1)) ==
              board.sum() with (int'(item == 2));
  }
endclass
