    end
    vif.drv_cb.penable <= 1;         // access phase
    forever begin
      @(vif.mon_cb);
      if (vif.mon_cb.presetn !== 1'b1) break;
      if ($isunknown(vif.mon_cb.pready))
        `uvm_fatal("XREADY", "PREADY unknown during access")
      if (vif.mon_cb.pready === 1'b1) begin
        if ($isunknown(vif.mon_cb.pslverr))
          `uvm_fatal("XERR", "PSLVERR unknown at completion")
        r.rdata  = vif.mon_cb.prdata;
        r.status = vif.mon_cb.pslverr ? APB_ERR : APB_OK;
        break;
      end
    end
    @(vif.drv_cb); idle();
  endtask

  task run_phase(uvm_phase phase);
    apb_item q, r;
    forever begin
      @(vif.drv_cb);
      idle();
      if (vif.drv_cb.presetn !== 1'b1) continue;
      q = null;
      seq_item_port.try_next_item(q);
      if (q == null) continue;
      r = apb_item::type_id::create("r");
      r.copy(q);
      r.set_id_info(q);
      transfer(q, r);
      seq_item_port.item_done(r);    // exactly one per acquired request
    end
  endtask
endclass
```

### Corner cases & pitfalls
- This driver leaves one idle cycle between transfers; simple, not maximum throughput (APB allows back-to-back setup).
- A hung transfer is caught by the test watchdog. Do not abandon an unfinished APB access and report a fake completion.
- If pins must clear asynchronously on reset, redesign pin ownership; never add a second thread writing the same pins.
- If reset is sampled at R3, the driver aborts and the monitor publishes no transfer for that access.

### Follow-ups
- *Why `r.copy(q)`?* So the response carries the request fields for the sequence's own checks.
- *Back-to-back transfers?* After completion, if another item is ready, drive the next setup at the following falling edge instead of idle.

