```systemverilog
class pattern_item;
  rand bit [7:0] a[];
  rand bit       write;
  bit            last_was_write;        // history: NOT rand

  constraint size_c { a.size() == 16; }

  // Zeros may repeat; a non-zero value never repeats back to back
  constraint nz_c { foreach (a[i]) if (i > 0 && a[i] != 0) a[i] != a[i-1]; }

  // Alternate READ / WRITE across calls
  constraint alt_c { write != last_was_write; }
  function void post_randomize();
    last_was_write = write;
  endfunction
endclass

// Exactly one run of ones in 16 bits: count rising starts
class one_run;
  rand bit [15:0] v;
  // bit i of (v & ~(v << 1)) is 1 where a run of ones starts
  constraint c { $countones(v & ~(v << 1)) == 1; }
endclass

// Simpler and clearer: randomize start and length, build in post_randomize
class one_run2;
  rand int unsigned start, len;
  bit [15:0] v;
  constraint c { start inside {[0:15]}; len inside {[1:16]}; start + len <= 16; } // bound first: no unsigned wrap
  function void post_randomize();
    v = ((17'h1 << len) - 1) << start;
  endfunction
endclass

// Symmetric array
//   foreach (a[i]) a[i] == a[a.size()-1-i];
```
`v & ~(v << 1)` has a 1 at each bit that starts a run (bit i set and bit i-1 clear, or i = 0), so one run means exactly one start bit. Without the `inside` bounds, `start + len <= 16` on `int unsigned` could be satisfied by a wrapped sum.

