### Code
```systemverilog
// Round-robin arbiter: rotate priority past the last winner
module rr_arb #(parameter int N = 4) (
  input  logic         clk, rst_n,
  input  logic [N-1:0] req,
  input  logic         accept,          // grant consumed this cycle
  output logic [N-1:0] grant
);
  logic [N-1:0]   mask;                 // 1s above the last winner
  logic [N-1:0]   req_m, g_m, g_u;
  assign req_m = req & mask;
  assign g_m   = req_m & ~(req_m - 1'b1);
  assign g_u   = req   & ~(req   - 1'b1);
  assign grant = (req_m != '0) ? g_m : g_u;

  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) mask <= '1;
    else if (accept && grant != '0)
      mask <= ~((grant << 1) - 1'b1);   // bits strictly above the winner
endmodule

// Saturating a*b + c (signed N-bit in, N-bit out)
module sat_mac #(parameter int N = 8) (
  input  logic signed [N-1:0] a, b, c,
  output logic signed [N-1:0] y
);
  localparam logic signed [2*N:0] MAX = (2*N+1)'((1 <<< (N-1)) - 1);
  localparam logic signed [2*N:0] MIN = -(2*N+1)'(1 <<< (N-1));
  logic signed [2*N:0] full;            // 2N+1 bits: no internal overflow
  assign full = a * b + c;
  assign y = (full > MAX) ? MAX[N-1:0] : (full < MIN) ? MIN[N-1:0] : full[N-1:0];
endmodule

// Sliding window count of ones over W bits
module win_ones #(parameter int W = 8) (
  input  logic clk, rst_n, din,
  output logic [$clog2(W+1)-1:0] cnt
);
  logic [W-1:0] sh;
  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) begin sh <= '0; cnt <= '0; end
    else begin
      sh  <= {sh[W-2:0], din};
      cnt <= cnt + din - sh[W-1];       // add entering bit, drop leaving bit
    end
endmodule
```

