  always_comb begin
    unique case (sel)
      2'd0: y_case = d[0];
      2'd1: y_case = d[1];
      2'd2: y_case = d[2];
      2'd3: y_case = d[3];
      default: y_case = 'x;             // only reached for X/Z sel in simulation
    endcase
