**Key idea:** Use a **conditional (implication / if-else) constraint** keyed on the command: e.g. writes must be 4-byte aligned, atomics 8-byte aligned, reads unrestricted. For power-of-two alignment constrain the **low address bits to zero** (solver-friendly) rather than using `%`.

### Code
```systemverilog
typedef enum bit [1:0] {READ, WRITE, ATOMIC} cmd_e;

class mem_txn;
  rand cmd_e      cmd;
  rand bit [31:0] addr;
  rand bit [2:0]  size;                     // bytes = 1 << size

  constraint c_range { addr inside {[32'h1000_0000 : 32'h1000_FFFF]}; }

  // Fixed alignment per command
  constraint c_align {
    if (cmd == WRITE)       addr[1:0] == 2'b00;     // 4-byte aligned
    else if (cmd == ATOMIC) addr[2:0] == 3'b000;    // 8-byte aligned
    // READ: byte aligned, no constraint
  }

  // Variant: alignment to the transfer size (natural alignment) for writes
  constraint c_nat_align {
    cmd == WRITE -> (addr & ((32'd1 << size) - 1)) == 0;
  }

  // Generic form for a non power-of-two granule (slower for the solver)
  // constraint c_mod { cmd == WRITE -> addr % ALIGN == 0; }   // ALIGN != 0
endclass

module tb;
  initial begin
    mem_txn t = new();
    repeat (6) begin
      if (!t.randomize()) $fatal(1, "randomize failed");
      $display("%-6s addr=%h size=%0d", t.cmd.name(), t.addr, 1 << t.size);
    end
  end
endmodule
```

