class arr_order;
  rand bit [7:0] a[];        // 1D dynamic
  rand bit [7:0] m[][];      // 2D dynamic (jagged allowed)
  bit [7:0]      f[3][4];    // fixed unpacked dims: size is in the type, NOT randomized via size()

  // ---- 1D ----
  constraint c_a_size  { a.size() inside {[4:8]}; }
  constraint c_a_val   { foreach (a[i]) a[i] inside {[10:50]}; }
  constraint c_a_order { foreach (a[i]) if (i > 0) a[i] > a[i-1]; }          // strictly ascending

  // ---- 2D ----
  constraint c_m_size  { m.size() == 3; foreach (m[i]) m[i].size() == 4; }  // rectangular 3x4
