class sym_matrix #(int N = 5);
  rand bit [3:0] a[N][N];
  rand bit [3:0] m[N][N];

  // Helper used only on (non-random) indices: legal and solver-friendly
  function int mirror(int j);
    return N - 1 - j;
  endfunction

  constraint c_val       { foreach (a[i, j]) a[i][j] inside {[0:9]}; }
  constraint c_transpose { foreach (a[i, j]) if (i < j) a[i][j] == a[j][i]; }      // a == a^T
  constraint c_mirror    { foreach (m[i, j]) if (j < N / 2) m[i][j] == m[i][mirror(j)]; } // left-right

  // ANTI-PATTERN: random data passed into a function inside a constraint
  // function bit is_sym(bit [3:0] x[N][N]); ... endfunction
  // constraint c_bad { is_sym(a) == 1; }
  //   -> 'a' is solved FIRST (without the symmetry constraint), then is_sym is evaluated;
  //      it is almost never 1, so randomize() fails.
endclass

module tb;
  initial begin
    sym_matrix #(5) s = new();
