class sudoku;
  rand bit [3:0] g[9][9];
  bit [3:0]      clue[9][9];          // 0 = empty, 1..9 = given

  constraint c_range { foreach (g[r, c]) g[r][c] inside {[1:9]}; }

  constraint c_clue  { foreach (g[r, c]) if (clue[r][c] != 0) g[r][c] == clue[r][c]; }

  // Pairwise form: same row OR same column OR same box -> different
  constraint c_units {
    foreach (g[r1, c1]) foreach (g[r2, c2])
      if ((r1 < r2 || (r1 == r2 && c1 < c2)) &&                       // each pair once
          (r1 == r2 || c1 == c2 || (r1 / 3 == r2 / 3 && c1 / 3 == c2 / 3)))
        g[r1][c1] != g[r2][c2];
  }

  function bit check();               // independent validation
    for (int u = 0; u < 9; u++) begin
      bit [9:0] row = 0, col = 0, box = 0;
      for (int k = 0; k < 9; k++) begin
        row[g[u][k]] = 1;
        col[g[k][u]] = 1;
        box[g[(u / 3) * 3 + k / 3][(u % 3) * 3 + k % 3]] = 1;
      end
      if (row != 10'h3FE || col != 10'h3FE || box != 10'h3FE) return 0;
    end
    return 1;
  endfunction
endclass

module tb;
  initial begin
    sudoku s = new();
    s.clue[0][0] = 5; s.clue[4][4] = 1; s.clue[8][8] = 9;     // a few clues
    if (!s.randomize()) $fatal(1, "no solution / conflicting clues");
    assert (s.check()) else $error("invalid grid");
    foreach (s.g[r]) $display("%p", s.g[r]);
  end
endmodule
```

### Explanation
- Each cell has 20 "peers" (8 row + 8 col + 4 extra box) → 81 x 20 / 2 = 810 inequality constraints.
- Alternative: `foreach (g[r]) unique {g[r]};` for rows plus helper arrays for columns/boxes (`unique {g[0][c], g[1][c], ..., g[8][c]}` written out) — fewer terms, faster.
- Box index: `(r/3, c/3)`; box cell k of box u: `g[(u/3)*3 + k/3][(u%3)*3 + k%3]`.

### Corner cases & pitfalls
- Conflicting clues (two 5s in a row) → randomize fails; check clues first for a clear error.
- Multiple solutions are legal for a sparse clue set; generating a puzzle with a **unique** solution is a different (search) problem.
- Solver time varies widely between tools for 810 pairwise constraints — the `unique` formulation is the usual fix.

