  rand bit [7:0] v;
  bit [7:0] forbidden[8];
  function new(bit [7:0] reference);
    bit [7:0] r = reference;
    for (int k = 0; k < 8; k++) begin
      forbidden[k] = r;
      r = {r[0], r[7:1]};
    end
  endfunction
  constraint avoid_c {
    foreach (forbidden[k]) v != forbidden[k];
  }
endclass
```

