a_lat: assert property (@(posedge clk) disable iff (!rst_n)
         $rose(req) |-> ##[MIN:MAX] ack);
// req and data stable until ack
a_stable: assert property (@(posedge clk) disable iff (!rst_n)
         req && !ack |=> req && $stable(data));
// no ack without req
a_noack: assert property (@(posedge clk) disable iff (!rst_n)
         ack |-> req);
// single ack per req (4-phase: req drops after ack)
a_once: assert property (@(posedge clk) disable iff (!rst_n)
         ack |=> !ack);
