module credit_chk #(int MAXC = 4, int W = 3) (
  input logic clk, rst_n,
  input logic send,                    // one credit consumed
  input logic rel_valid, rel_ack,      // release handshake
  input logic [W-1:0] rel_cnt          // credits returned by this release
);
  int credits;
  wire rel_fire = rel_valid && rel_ack;

  // Auxiliary state: the part SVA cannot express alone
  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) credits <= MAXC;
    else        credits <= credits - send + (rel_fire ? rel_cnt : 0);

  a_no_send_at_zero: assert property (@(posedge clk) disable iff (!rst_n)
                       send |-> credits > 0);
  a_bounds:          assert property (@(posedge clk) disable iff (!rst_n)
                       credits inside {[0:MAXC]});
  a_rel_stable:      assert property (@(posedge clk) disable iff (!rst_n)
                       rel_valid && !rel_ack |=> rel_valid && $stable(rel_cnt));
  a_rel_nonzero:     assert property (@(posedge clk) disable iff (!rst_n)
                       rel_valid |-> rel_cnt != 0);
  a_ack_latency:     assert property (@(posedge clk) disable iff (!rst_n)
                       $rose(rel_valid) |-> ##[0:8] rel_ack);

  c_full_return:     cover property (@(posedge clk) credits == MAXC ##1 send ##[1:$] credits == 0 ##[1:$] credits == MAXC);
  c_send_and_rel:    cover property (@(posedge clk) send && rel_fire);
endmodule
// bind credit_chk dut_if_chk(.clk(clk), .rst_n(rst_n), .send(tx_valid & tx_ready), ...);
