class lane_remap #(int NPHY = 6, int NLOG = 4);
  bit        failed[NPHY];            // set by the test before randomize
  rand int unsigned map[NLOG];        // map[logical] = physical
  bit        monotonic = 1;           // keep lane order (common rule)
  bit        contiguous_only = 0;     // optional stronger rule

  constraint c_range  { foreach (map[i]) map[i] < NPHY; }
  constraint c_healthy{ foreach (map[i]) !failed[map[i]]; }
  constraint c_unique { unique {map}; }
  constraint c_order  { monotonic -> foreach (map[i]) if (i > 0) map[i] > map[i-1]; }
  constraint c_contig { contiguous_only -> foreach (map[i]) if (i > 0) map[i] == map[i-1] + 1; }

  function void pre_randomize();
    int healthy = 0;
    foreach (failed[p]) if (!failed[p]) healthy++;
    if (healthy < NLOG)
      $fatal(1, "only %0d healthy lanes for %0d logical lanes", healthy, NLOG);
  endfunction
endclass

