```systemverilog
class delay_sweep_seq extends uvm_sequence;
  `uvm_object_utils(delay_sweep_seq)
  phy_reg_block   regm;
  int unsigned    NCODES = 32, SETTLE = 64, WINDOW = 4096, ERR_THR = 0;
  int unsigned    errs[];

  function new(string name = "delay_sweep_seq"); super.new(name); endfunction

  task body();
    uvm_status_e st; uvm_reg_data_t v;
    int best_lo = -1, best_len = 0, lo = -1;
    errs = new[NCODES];
    for (int c = 0; c < NCODES; c++) begin
      regm.DELAY_CODE.write(st, c);
      regm.ERR_CNT_CLR.write(st, 1);
      wait_cycles(SETTLE);                       // let the delay line settle
      regm.PRBS_EN.write(st, 1);
      wait_cycles(WINDOW);
      regm.PRBS_EN.write(st, 0);
      regm.ERR_CNT.read(st, v);
      errs[c] = v;
      // track longest run of passing codes
      if (errs[c] <= ERR_THR) begin
        if (lo < 0) lo = c;
        if (c - lo + 1 > best_len) begin best_len = c - lo + 1; best_lo = lo; end
      end else lo = -1;
    end
    if (best_len == 0) `uvm_fatal("SWEEP", "no passing delay code: eye closed")
    regm.DELAY_CODE.write(st, best_lo + best_len/2);
    `uvm_info("SWEEP", $sformatf("eye [%0d:%0d], center %0d", best_lo, best_lo+best_len-1, best_lo+best_len/2), UVM_LOW)
  endtask

  task wait_cycles(int n);
    // implemented via a config_db clock vif or a delay agent
  endtask
endclass
```

