  { "name": "pulse", "wave": "0.10.10..10...10.." },
  { "name": "gap",   "wave": "x.=..=...=....=...", "data": ["first","3","4","5"] }
],
  "head": { "text": "gap = cycles between consecutive rising edges: 3, 4, 5 ... 250, then 3 again" } }
```

### Code
```systemverilog
module pulse_train_chk #(parameter int MIN_GAP = 3, parameter int MAX_GAP = 250) (
  input logic clk, rst_n, start, pulse
);
  logic pulse_d;
  int   cnt;        // 距離上一個 rising edge 的 cycle 數
  int   exp_gap;    // 下一個 edge 預期的間隔
  bit   armed;      // 看過 start
  bit   have_ref;   // start 之後已經看過第一個 edge
  wire  rise = pulse && !pulse_d;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pulse_d <= 1'b0; cnt <= 0; exp_gap <= MIN_GAP; armed <= 1'b0; have_ref <= 1'b0;
    end else begin
      pulse_d <= pulse;
      if (start) begin                       // 中途 restart：丟掉歷史，從 3 重新開始
        armed <= 1'b1; have_ref <= 1'b0; exp_gap <= MIN_GAP; cnt <= 0;
      end else if (rise) begin
        if (!armed)
          $error("%0t: pulse without start", $time);
        else if (have_ref && cnt != exp_gap)
          $error("%0t: gap=%0d expected %0d", $time, cnt, exp_gap);
        if (have_ref) exp_gap <= (exp_gap == MAX_GAP) ? MIN_GAP : exp_gap + 1;
        have_ref <= 1'b1;
        cnt      <= 1;
      end else if (have_ref) begin
        if (cnt == exp_gap)                   // 這一拍應該要有 edge
          $error("%0t: missing pulse, expected gap %0d", $time, exp_gap);
        cnt <= cnt + 1;
      end
    end
  end
endmodule
```

### Trace（gap = 3）
| cycle | rise | cnt（cycle 開始時） | 動作 |
| --- | --- | --- | --- |
| t | 1 | – | `cnt <= 1` |
| t+1 | 0 | 1 | `cnt <= 2` |
| t+2 | 0 | 2 | `cnt <= 3` |
| t+3 | 1 | 3 | `3 == exp_gap` → pass，`exp_gap <= 4` |

### Corner cases & pitfalls
- **中途 reset**：之後 `armed = 0`，下一個 start 之前出現任何 pulse 都是 error。
- **序列中途又來 start**：`start` 優先，間隔從 3 重新開始；如果 spec 規定忽略中途的 start，就改成 `if (start && !have_ref)`。
- **start 到第一個 pulse 的延遲**：spec 有定義的話，從 `start` 就開始計數並檢查。
- 250 → 3 的繞回、pulse 寬度大於 1 cycle（只看 rising edge 所以不受影響）、`start` 和 `pulse` 同一拍。
- 先釐清「間隔」是 edge 到 edge，還是 pulse 之間 low 的 cycle 數（兩者差 1）。

### Follow-ups
- *怎麼確認整個序列都跑過？* 用 coverpoint 收 `exp_gap`（3..250 每個值），加上「250 → 3 繞回」的 transition bin。
- *用 SVA 寫？* 間隔會遞增，SVA 需要 local variable 加上外部的 `exp_gap` model，反而更難讀；這種「有狀態」的檢查用 counter 版 checker 較清楚，SVA 適合用來補 `start |-> !pulse` 這類簡單規則。

**重點：** SV 有 array locator method `unique()`，可以直接回傳不重複的元素（但**不保證順序**）。不能用的話：用 associative array 當 `seen` set，一次掃描、保留第一次出現的順序，時間 O(n)；或先 `sort()` 再用雙指標原地去重，時間 O(n log n)、額外空間 O(1)。

| 步驟 | 元素 | `seen` 有嗎？ | out |
| --- | --- | --- | --- |
| 0 | 3 | 否 | {3} |
| 1 | 1 | 否 | {3,1} |
| 2 | 3 | 是 → 跳過 | {3,1} |
| 3 | 2 | 否 | {3,1,2} |
| 4 | 1 | 是 → 跳過 | {3,1,2} |

### Code
```systemverilog
module dedup_demo;
  // 1) 內建方法：結果順序不保證
  function automatic void builtin_way(int a[$]);
    int u[$] = a.unique();
    $display("unique(): %p", u);
  endfunction

  // 2) O(n)、保留第一次出現的順序
  function automatic void dedup_keep_order(ref int q[$]);
    bit seen[int];
    int out[$];
    foreach (q[i])
      if (!seen.exists(q[i])) begin
        seen[q[i]] = 1'b1;
        out.push_back(q[i]);
      end
    q = out;
  endfunction

  // 3) 不准用額外資料結構：sort + 雙指標，原地處理
  function automatic void dedup_sorted(ref int a[]);
    int w = 0;
    if (a.size() == 0) return;
    a.sort();
    for (int r = 1; r < a.size(); r++)
      if (a[r] != a[w]) begin
        w++;
        a[w] = a[r];
      end
    a = new[w + 1](a);      // 縮小並保留前 w+1 個
  endfunction

  initial begin
    int q[$] = '{3, 1, 3, 2, 1};
    int d[]  = '{3, 1, 3, 2, 1};
    builtin_way(q);
    dedup_keep_order(q);  $display("keep order: %p", q);   // '{3, 1, 2}
    dedup_sorted(d);      $display("sorted:     %p", d);   // '{1, 2, 3}
  end
endmodule
```

### Explanation
- `unique()` 對 queue、dynamic、fixed、associative array 都可用；`unique_index()` 回傳索引。
- associative array 的 `exists()` 是平均 O(1) 查詢，所以整體是 O(n)。
- 如果連 sort 都不准用：雙層迴圈 O(n²)，對每個元素檢查前面有沒有出現過。

### Corner cases & pitfalls
- 空陣列、只有一個元素、全部相同、全部不同。
- 對 4-state 的 `logic` 陣列，`==` 遇到 X 會得到 X（if 視為 false），要用 `!==` / `===`。
- 在 `foreach` 迴圈裡直接 `delete()` 原陣列會讓索引錯位，所以另外建 `out`。

### Follow-ups
- *只要找出重複了哪些值？* 用 `int cnt[int]` 計數，再找 `cnt > 1` 的 key。
- *對 class object 去重？* 用 key（例如 `addr`）當 associative array 的 index，或用 `unique with (item.addr)`。

**重點：** 遞迴寫法直接翻譯定義 `F(n) = F(n-1) + F(n-2)`，但會重複計算子問題，時間 **O(φⁿ) ≈ O(1.618ⁿ)**、stack 深度 O(n)。迭代寫法只保留前兩項，時間 **O(n)**、空間 **O(1)**。加上 memo 的遞迴也是 O(n)。

```mermaid
flowchart TD
  F4["F(4)"] --> F3["F(3)"]
  F4 --> F2a["F(2)"]
  F3 --> F2b["F(2)"]
  F3 --> F1a["F(1)"]
  F2a --> F1b["F(1)"]
  F2a --> F0a["F(0)"]
  F2b --> F1c["F(1)"]
  F2b --> F0b["F(0)"]
```
F(2) 被算了兩次；n 越大重複越多，呼叫次數本身就以費氏數列的速度成長。

| 方法 | 時間 | 空間 |
| --- | --- | --- |
| 單純遞迴 | O(φⁿ) | O(n)（stack） |
| 遞迴 + memo | O(n) | O(n) |
| 迭代 | O(n) | O(1) |
| 矩陣快速冪 | O(log n) | O(1) |

### Code
```cpp
#include <cstdint>
#include <iostream>
#include <vector>

// 1) 單純遞迴：最直觀，但是指數時間
uint64_t fib_rec(int n) {
    if (n < 2) return n;                 // base case：F(0)=0, F(1)=1
    return fib_rec(n - 1) + fib_rec(n - 2);
}

// 2) 遞迴 + memo：每個子問題只算一次
uint64_t fib_memo(int n, std::vector<int64_t>& memo) {
    if (n < 2) return n;
    if (memo[n] >= 0) return memo[n];
    return memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
}

// 3) 迭代：O(n) 時間、O(1) 空間
uint64_t fib_iter(int n) {
    uint64_t a = 0, b = 1;               // a = F(i), b = F(i+1)
    for (int i = 0; i < n; ++i) {
        uint64_t t = a + b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    std::vector<int64_t> memo(91, -1);
    for (int n : {0, 1, 2, 10, 50})
        std::cout << n << ": " << fib_iter(n) << " " << fib_memo(n, memo) << "\n";
    std::cout << fib_rec(20) << "\n";    // 6765；n=50 時遞迴版要跑非常久
}
```

### Corner cases & pitfalls
- `n = 0`、`n = 1`、負數輸入（要定義行為或回報錯誤）。
- overflow：`uint64_t` 只能放到 F(93)；`int64_t` 只到 F(92)；更大的要用大數。
- 單純遞迴在 n 很大時會 stack overflow；面試時要主動提出迭代版本。

### Follow-ups
- *O(log n) 怎麼做？* `[[1,1],[1,0]]^n` 用快速冪，或 fast doubling：`F(2k) = F(k)(2F(k+1) − F(k))`、`F(2k+1) = F(k)² + F(k+1)²`。
- *用硬體算？* 兩個暫存器加一個加法器，每個 cycle 算出一項：`{a, b} <= {b, a + b}`。

**重點：** 遞迴 = **base case** + **把問題縮小的遞迴關係**。`fib(n) = fib(n-1) + fib(n-2)`，base case 是 `fib(0) = 0`、`fib(1) = 1`。每次呼叫會在 call stack 上推一個 frame，等兩個子呼叫回傳後相加再 pop。最大 stack 深度是 n，但總呼叫次數呈指數成長，因為同一個子問題被重算很多次。

### `fib(4)` 的執行順序（call stack）
| 步驟 | 動作 | stack（底 → 頂） | 回傳 |
| --- | --- | --- | --- |
| 1 | call fib(4) | 4 | |
| 2 | call fib(3) | 4, 3 | |
| 3 | call fib(2) | 4, 3, 2 | |
| 4 | call fib(1) | 4, 3, 2, 1 | 1 |
| 5 | call fib(0) | 4, 3, 2, 0 | 0 |
| 6 | fib(2) 完成 | 4, 3 | 1 |
| 7 | call fib(1) | 4, 3, 1 | 1 |
| 8 | fib(3) 完成 | 4 | 2 |
| 9 | call fib(2)（**重算**） | 4, 2 | 1（經過 fib(1)、fib(0)） |
| 10 | fib(4) 完成 | – | **3** |

總共 9 次呼叫；`fib(n)` 的呼叫次數是 `2·fib(n+1) − 1`，所以時間是 O(φⁿ)。

### Code
```c
#include <stdio.h>
#include <stdint.h>

/* 單純遞迴：時間 O(phi^n)、stack 深度 O(n) */
uint64_t fib(int n) {
    if (n <= 1)                 /* base case：沒有它就會無限遞迴 */
        return (uint64_t)n;
    return fib(n - 1) + fib(n - 2);
}

/* 遞迴 + memo：每個 n 只算一次，時間 O(n) */
static uint64_t memo[94];
static int      known[94];

uint64_t fib_memo(int n) {
    if (n <= 1) return (uint64_t)n;
    if (!known[n]) {
        memo[n]  = fib_memo(n - 1) + fib_memo(n - 2);
        known[n] = 1;
    }
    return memo[n];
}

int main(void) {
    printf("%llu %llu\n", (unsigned long long)fib(10),
                          (unsigned long long)fib_memo(90));   /* 55 2880067194370816120 */
    return 0;
}
```

### Corner cases & pitfalls
- 沒寫 base case、或 base case 寫錯（例如只處理 `n == 1`，`fib(0)` 就會變成 `fib(-1)` 無限遞迴）。
- 負數輸入：要先檢查。
- 遞迴太深會 stack overflow；`uint64_t` 在 `n > 93` 會 overflow。
- 面試時要主動說：「這個寫法很直觀，但效率差，可以改成 memo 或迭代。」

### Follow-ups
- *遞迴和迭代怎麼選？* 遞迴好寫、好讀，適合 tree / divide-and-conquer；迭代沒有 stack 開銷。fib 用迭代：`a, b = b, a + b`，O(n) 時間、O(1) 空間。
- *什麼是 tail recursion？* 遞迴呼叫是最後一個動作：`fib_t(n, a, b) = n == 0 ? a : fib_t(n-1, b, a+b)`，compiler 可以把它優化成迴圈。

**重點：** 用三個指標 `prev`、`curr`、`next` 走過 list：先記住 `next = curr->next`，把 `curr->next` 指回 `prev`，再整體往前移一格。時間 O(n)、空間 O(1)。最後 `prev` 就是新的 head。

### Trace（`1 → 2 → 3 → null`）
| 迭代 | prev | curr | next | 動作後的 list |
| --- | --- | --- | --- | --- |
| 開始 | null | 1 | – | `1→2→3` |
| 1 | 1 | 2 | 2 | `null←1`、`2→3` |
| 2 | 2 | 3 | 3 | `null←1←2`、`3` |
| 3 | 3 | null | null | `null←1←2←3` |
| 結束 | **head = 3** | | | `3→2→1→null` |

### Code
```cpp
#include <iostream>

struct Node {
    int   val;
    Node* next;
    explicit Node(int v, Node* n = nullptr) : val(v), next(n) {}
};

// 迭代：O(n) 時間、O(1) 空間
Node* reverseList(Node* head) {
    Node* prev = nullptr;
    Node* curr = head;
    while (curr) {
        Node* next = curr->next;   // 1. 先存下一個
        curr->next = prev;         // 2. 反轉指標
        prev = curr;               // 3. 往前移
        curr = next;
    }
    return prev;                   // 新的 head
}

// 遞迴：O(n) 時間、O(n) stack
Node* reverseRec(Node* head) {
    if (!head || !head->next) return head;
    Node* newHead = reverseRec(head->next);
    head->next->next = head;       // 讓下一個節點指回自己
    head->next = nullptr;
    return newHead;
}

int main() {
    Node* h = new Node(1, new Node(2, new Node(3)));
    h = reverseList(h);
    for (Node* p = h; p; p = p->next) std::cout << p->val << ' ';   // 3 2 1
    std::cout << '\n';
    while (h) { Node* n = h->next; delete h; h = n; }                 // 釋放記憶體
}
```

### Corner cases & pitfalls
- 空 list（`head == nullptr`）、只有一個節點：兩個版本都直接回傳 head。
- 忘記先存 `next` 就改 `curr->next`，後面的 list 就斷了。
- 遞迴版忘記 `head->next = nullptr`，會在最後兩個節點之間形成 cycle。
- 很長的 list 用遞迴會 stack overflow。

### Follow-ups
- *只反轉第 m 到 n 個節點？* 走到 m-1 的位置，在區間內做同樣的三指標反轉，再接回頭尾。
- *每 k 個一組反轉？* 每組反轉後把前一組的尾巴接到這一組新的頭。
- *雙向 list？* 每個節點交換 `prev` / `next` 即可。

**重點：** peak 的定義是「**嚴格遞增**再**嚴格遞減**」的連續子陣列，長度至少 3。先找出所有頂點 `a[i-1] < a[i] > a[i+1]`，再從頂點往左、往右延伸到不能再嚴格遞增 / 遞減為止，長度 = `r - l + 1`，取最大值。每個元素最多被看兩次，時間 O(n)、空間 O(1)。

### Trace（`[1, 3, 1, 2, 4, 6, 5]`）
| 頂點 i | a[i] | 往左延伸到 l | 往右延伸到 r | peak | 長度 |
| --- | --- | --- | --- | --- | --- |
| 1 | 3 | 0 | 2 | `1,3,1` | 3 |
| 5 | 6 | 2 | 6 | `1,2,4,6,5` | **5** |

`[1, 1, 2, 3, 2, 2]`：頂點 i=3，l=1（`a[0] == a[1]`，不是嚴格遞增），r=4 → 長度 4。`[2,2,2,2,2,2]`：沒有頂點 → 沒有 peak。

### Code
```cpp
#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

// 回傳 {是否有 peak, 最長 peak 的長度}
std::pair<bool, int> longestPeak(const std::vector<int>& a) {
    const int n = static_cast<int>(a.size());
    int best = 0;
    int i = 1;
    while (i < n - 1) {
        if (!(a[i - 1] < a[i] && a[i] > a[i + 1])) { ++i; continue; }   // 不是頂點
        int l = i - 1;
        while (l > 0 && a[l - 1] < a[l]) --l;          // 往左：嚴格遞增
        int r = i + 1;
        while (r < n - 1 && a[r] > a[r + 1]) ++r;      // 往右：嚴格遞減
        best = std::max(best, r - l + 1);
        i = r;                                         // 下一個頂點不可能在 r 之前
    }
    return {best > 0, best};
}

int main() {
    for (const auto& v : std::vector<std::vector<int>>{
             {1, 1, 2, 3, 2, 2}, {2, 2, 2, 2, 2, 2}, {1, 3, 1, 2, 4, 6, 5}}) {
        auto [has, len] = longestPeak(v);
        std::cout << (has ? "has peak, length " : "no peak, length ") << len << '\n';
    }
}
```
輸出：`has peak, length 4` / `no peak, length 0` / `has peak, length 5`。

### Corner cases & pitfalls
- 長度小於 3 的陣列：迴圈不執行，回傳沒有 peak。
- 平台（相等值）會打斷 peak：`[1,2,2,1]` 沒有 peak，所以比較要用嚴格的 `<`、`>`。
- 只有遞增（`[1,2,3]`）或只有遞減，都不算 peak。
- 相鄰的兩個 peak 共用谷底元素（例如 `1,3,1,2`）是允許的，所以跳到 `i = r` 而不是 `r + 1`。

### Follow-ups
- *一次掃描的寫法？* 維護 `up`、`down` 兩個計數：遞增時若 `down > 0` 就重設；遇到相等就兩者歸零；`up > 0 && down > 0` 時更新答案 `up + down + 1`。
- *要回傳 peak 的起訖位置？* 更新 `best` 時一併記下 `l`、`r`。

**Key idea:** Bundle settings into a **hierarchy of configuration objects** (`env_cfg` holding one `agent_cfg` per agent), build and randomize them **once in the test**, push the top object down with a **single `uvm_config_db::set`**, and let each level hand the sub-object to its children. That gives one lookup per level instead of hundreds of scattered `set`/`get` calls on individual fields.

```mermaid
flowchart TD
  TB["tb_top: set vif handles"] --> TEST["uvm_test: create and randomize env_cfg"]
  TEST -->|set env cfg| ENV["uvm_env: get env_cfg"]
  ENV -->|set agt0 cfg| A0["agent 0: get agent_cfg"]
  ENV -->|set agt1 cfg| A1["agent 1: get agent_cfg"]
  ENV -->|handle| SCB["scoreboard"]
  A0 --> D0["driver and monitor read cfg.vif"]
```

