    vector<pair<string, int>> v(cnt.begin(), cnt.end());
    size_t k = min<size_t>(5, v.size());
    partial_sort(v.begin(), v.begin() + k, v.end(),
                 [](const auto& a, const auto& b) { return a.second > b.second; });
    for (size_t i = 0; i < k; i++) cout << v[i].second << "  " << v[i].first << "\n";
}

int main(int argc, char** argv) {
    auto errs = errors(argc > 1 ? argv[1] : "sim.log");
    if (!errs.empty()) cout << "first error @ " << errs[0].t << " [" << errs[0].tag << "]\n";
    top5(errs);
}
```

### Corner cases & pitfalls
- Building the `regex` inside the loop recompiles it every line: very slow.
- `std::regex` is slow in general; for a 20 GB log, prefilter with `line.compare(0, 9, "UVM_ERROR") == 0` before the regex, or parse by hand.
- Messages containing run-specific numbers (addresses) defeat the top-5 count; normalize digits first (`regex_replace(msg, regex(R"(0x[0-9a-fA-F]+|\d+)"), "N")`).

