namespace fs = std::filesystem;
using namespace std;

struct LogStats { unordered_map<string, int> sev; bool has_summary = false; };

LogStats scan(const string& path) {
    static const unordered_set<string> SEV =
        {"UVM_INFO", "UVM_WARNING", "UVM_ERROR", "UVM_FATAL"};
    LogStats s;
    ifstream f(path);
    string line;
    while (getline(f, line)) {
        if (line.find("UVM Report Summary") != string::npos) s.has_summary = true;
        istringstream ss(line);
        string sev, next;
        ss >> sev >> next;
        if (SEV.count(sev) && next != ":") s.sev[sev]++;
    }
    return s;
}

map<string, string> summarize(const string& dir) {
    map<string, string> result;                       // sorted by test name
    for (const auto& e : fs::directory_iterator(dir)) {
        if (!e.is_regular_file() || e.path().extension() != ".log") continue;
        LogStats s = scan(e.path().string());
        int bad = s.sev["UVM_ERROR"] + s.sev["UVM_FATAL"];
        result[e.path().stem().string()] = (bad || !s.has_summary) ? "FAIL" : "PASS";
    }
    return result;
}

int main(int argc, char** argv) {
    auto res = summarize(argc > 1 ? argv[1] : "logs");
    ofstream out("report.csv");
    out << "test,status\n";
    int fails = 0;
    for (const auto& [t, s] : res) {
        cout << t << "  " << s << "\n";
        out << t << ',' << s << '\n';
        fails += (s == "FAIL");
    }
    cout << res.size() - fails << "/" << res.size() << " passed\n";
    return fails ? 1 : 0;                              // CI-friendly exit code
}
