```verilog
module div1p5 (input clk, input rst_n, output clk_out);
  reg [1:0] cnt;
  reg a, b;
  always @(posedge clk or negedge rst_n)
    if (!rst_n) cnt <= 2'd0;
    else        cnt <= (cnt == 2'd2) ? 2'd0 : cnt + 2'd1;

  always @(posedge clk or negedge rst_n)    // high while cnt == 0
    if (!rst_n) a <= 1'b0;
    else        a <= (cnt == 2'd2);

  always @(negedge clk or negedge rst_n)    // high from 1.5T to 2.5T
    if (!rst_n) b <= 1'b0;
    else        b <= (cnt == 2'd1);

  assign clk_out = a | b;
endmodule
```

### Explanation
- 在 3T 的時間內需要兩個輸出週期 → 一個由 posedge 觸發、一個由 negedge 觸發。
